using Lumoin.Veridical.Longfellow;
using System;
using System.Security.Cryptography;
using System.Security.Cryptography.X509Certificates;

namespace Lumoin.Veridical.Tests.TestInfrastructure;

/// <summary>
/// A P-256 key as fixed-width big-endian components: the private scalar and the two public
/// coordinates, each 32 bytes. The shape is the one every platform backend accepts, so a key
/// generated by one provider can be signed with, or have its public point read, by the tests
/// without knowing which provider produced it.
/// </summary>
internal sealed class PlatformP256Key
{
    /// <summary>The width in bytes of the scalar and of each coordinate.</summary>
    public const int ComponentSize = 32;

    /// <summary>The width in bytes of an IEEE P1363 signature, the concatenation of r and s.</summary>
    public const int SignatureSize = 2 * ComponentSize;


    /// <summary>Creates a key from its three 32-byte components.</summary>
    /// <param name="privateKey">The private scalar <c>d</c>, big-endian, 32 bytes.</param>
    /// <param name="publicX">The public point's x-coordinate, big-endian, 32 bytes.</param>
    /// <param name="publicY">The public point's y-coordinate, big-endian, 32 bytes.</param>
    public PlatformP256Key(byte[] privateKey, byte[] publicX, byte[] publicY)
    {
        PrivateKey = privateKey;
        PublicX = publicX;
        PublicY = publicY;
    }


    /// <summary>The private scalar <c>d</c>, big-endian, 32 bytes.</summary>
    public byte[] PrivateKey { get; }

    /// <summary>The public point's x-coordinate, big-endian, 32 bytes.</summary>
    public byte[] PublicX { get; }

    /// <summary>The public point's y-coordinate, big-endian, 32 bytes.</summary>
    public byte[] PublicY { get; }


    /// <summary>Writes the public point in SEC1 compressed form: a parity tag byte, then the x-coordinate.</summary>
    /// <param name="destination">The 33-byte buffer receiving the compressed point.</param>
    public void ExportCompressedPublicKey(Span<byte> destination)
    {
        destination[0] = (byte)(0x02 | (PublicY[^1] & 0x01));
        PublicX.CopyTo(destination[1..]);
    }
}


/// <summary>Generates a fresh P-256 key pair.</summary>
/// <returns>The new key.</returns>
internal delegate PlatformP256Key PlatformP256GenerateDelegate();


/// <summary>Signs a message with ECDSA over P-256 and SHA-256, writing the IEEE P1363 signature r followed by s.</summary>
/// <param name="key">The signing key.</param>
/// <param name="message">The message that is hashed and signed.</param>
/// <param name="signature">Receives the 64-byte signature.</param>
internal delegate void PlatformP256SignDelegate(PlatformP256Key key, ReadOnlySpan<byte> message, Span<byte> signature);


/// <summary>Verifies an IEEE P1363 ECDSA signature over P-256 against the SHA-256 of a message.</summary>
/// <param name="publicX">The public point's x-coordinate, 32 bytes.</param>
/// <param name="publicY">The public point's y-coordinate, 32 bytes.</param>
/// <param name="message">The message that was signed.</param>
/// <param name="signature">The 64-byte signature.</param>
/// <returns><see langword="true"/> when the signature is valid for the message under the key.</returns>
internal delegate bool PlatformP256VerifyDelegate(ReadOnlySpan<byte> publicX, ReadOnlySpan<byte> publicY, ReadOnlySpan<byte> message, ReadOnlySpan<byte> signature);


/// <summary>Verifies an IEEE P1363 ECDSA signature over P-256 against a digest that was computed by the caller.</summary>
/// <param name="publicX">The public point's x-coordinate, 32 bytes.</param>
/// <param name="publicY">The public point's y-coordinate, 32 bytes.</param>
/// <param name="digest">The 32-byte digest that was signed.</param>
/// <param name="signature">The 64-byte signature.</param>
/// <returns><see langword="true"/> when the signature is valid for the digest under the key.</returns>
internal delegate bool PlatformP256VerifyDigestDelegate(ReadOnlySpan<byte> publicX, ReadOnlySpan<byte> publicY, ReadOnlySpan<byte> digest, ReadOnlySpan<byte> signature);


/// <summary>Computes the raw ECDH shared secret over P-256: the x-coordinate of the product of the own private scalar and the peer's public point.</summary>
/// <param name="own">The own key, whose private scalar and public point are used.</param>
/// <param name="peerX">The peer's public x-coordinate, 32 bytes.</param>
/// <param name="peerY">The peer's public y-coordinate, 32 bytes.</param>
/// <param name="secret">Receives the 32-byte shared secret.</param>
internal delegate void PlatformP256AgreeDelegate(PlatformP256Key own, ReadOnlySpan<byte> peerX, ReadOnlySpan<byte> peerY, Span<byte> secret);


/// <summary>Reads the public key of a DER-encoded X.509 certificate.</summary>
/// <param name="certificate">The DER certificate.</param>
/// <param name="publicX">Receives the 32-byte x-coordinate when the key is a P-256 key.</param>
/// <param name="publicY">Receives the 32-byte y-coordinate when the key is a P-256 key.</param>
/// <returns><see langword="true"/> when the certificate carries a P-256 public key; <see langword="false"/> for any other key type.</returns>
/// <exception cref="CryptographicException">The certificate cannot be parsed.</exception>
internal delegate bool PlatformCertificatePublicKeyDelegate(ReadOnlySpan<byte> certificate, Span<byte> publicX, Span<byte> publicY);


/// <summary>
/// The platform cryptography the tests use as an independent oracle or as a signing and key
/// generation source: single-block AES, P-256 ECDSA, P-256 ECDH and the public key of an X.509
/// certificate. Each operation is a named delegate behind a settable static getter. The defaults
/// call the .NET cryptography classes; the browser-wasm runtime has no implementation of them, so
/// its host replaces the providers at startup with ones backed by the JavaScript environment
/// before any test runs. Tests call the members here and never the platform classes directly.
/// </summary>
internal static class TestPlatformCrypto
{
    /// <summary>Encrypts one block in ECB mode with no padding; the key length selects AES-128, AES-192 or AES-256.</summary>
    public static LongfellowBlockCipherDelegate AesEncryptBlock { get; set; } = NativeAesEncryptBlock;

    /// <summary>Generates a P-256 key pair.</summary>
    public static PlatformP256GenerateDelegate GenerateP256Key { get; set; } = NativeGenerateP256Key;

    /// <summary>Signs a message with ECDSA over P-256 and SHA-256 into the IEEE P1363 form.</summary>
    public static PlatformP256SignDelegate SignP256 { get; set; } = NativeSignP256;

    /// <summary>Verifies an IEEE P1363 P-256 signature over the SHA-256 of a message.</summary>
    public static PlatformP256VerifyDelegate VerifyP256 { get; set; } = NativeVerifyP256;

    /// <summary>Verifies an IEEE P1363 P-256 signature over a caller-computed digest.</summary>
    public static PlatformP256VerifyDigestDelegate VerifyP256Digest { get; set; } = NativeVerifyP256Digest;

    /// <summary>Computes the raw P-256 ECDH shared secret.</summary>
    public static PlatformP256AgreeDelegate AgreeP256 { get; set; } = NativeAgreeP256;

    /// <summary>Reads the P-256 public key of a DER X.509 certificate.</summary>
    public static PlatformCertificatePublicKeyDelegate ReadCertificatePublicKey { get; set; } = NativeReadCertificatePublicKey;


    private static void NativeAesEncryptBlock(ReadOnlySpan<byte> key, ReadOnlySpan<byte> input, Span<byte> output)
    {
        using Aes aes = Aes.Create();
        aes.SetKey(key);
        aes.EncryptEcb(input, output, PaddingMode.None);
    }


    private static PlatformP256Key NativeGenerateP256Key()
    {
        using ECDsa ecdsa = ECDsa.Create(ECCurve.NamedCurves.nistP256);
        ECParameters parameters = ecdsa.ExportParameters(includePrivateParameters: true);

        return new PlatformP256Key(
            LeftPad(parameters.D),
            LeftPad(parameters.Q.X),
            LeftPad(parameters.Q.Y));
    }


    private static void NativeSignP256(PlatformP256Key key, ReadOnlySpan<byte> message, Span<byte> signature)
    {
        using ECDsa ecdsa = ECDsa.Create(ToParameters(key.PrivateKey, key.PublicX, key.PublicY));
        ecdsa.SignData(message, signature, HashAlgorithmName.SHA256, DSASignatureFormat.IeeeP1363FixedFieldConcatenation);
    }


    private static bool NativeVerifyP256(ReadOnlySpan<byte> publicX, ReadOnlySpan<byte> publicY, ReadOnlySpan<byte> message, ReadOnlySpan<byte> signature)
    {
        using ECDsa ecdsa = ECDsa.Create(ToParameters(null, publicX, publicY));

        return ecdsa.VerifyData(message, signature, HashAlgorithmName.SHA256, DSASignatureFormat.IeeeP1363FixedFieldConcatenation);
    }


    private static bool NativeVerifyP256Digest(ReadOnlySpan<byte> publicX, ReadOnlySpan<byte> publicY, ReadOnlySpan<byte> digest, ReadOnlySpan<byte> signature)
    {
        using ECDsa ecdsa = ECDsa.Create(ToParameters(null, publicX, publicY));

        return ecdsa.VerifyHash(digest, signature, DSASignatureFormat.IeeeP1363FixedFieldConcatenation);
    }


    private static void NativeAgreeP256(PlatformP256Key own, ReadOnlySpan<byte> peerX, ReadOnlySpan<byte> peerY, Span<byte> secret)
    {
        using ECDiffieHellman ownKey = ECDiffieHellman.Create(ToParameters(own.PrivateKey, own.PublicX, own.PublicY));
        using ECDiffieHellman peerKey = ECDiffieHellman.Create(ToParameters(null, peerX, peerY));
        byte[] derived = ownKey.DeriveRawSecretAgreement(peerKey.PublicKey);
        derived.CopyTo(secret);
    }


    private static bool NativeReadCertificatePublicKey(ReadOnlySpan<byte> certificate, Span<byte> publicX, Span<byte> publicY)
    {
        using X509Certificate2 parsed = X509CertificateLoader.LoadCertificate(certificate);
        using ECDsa? key = parsed.GetECDsaPublicKey();
        if(key is null)
        {
            return false;
        }

        ECParameters parameters = key.ExportParameters(includePrivateParameters: false);
        if(parameters.Q.X is not { Length: PlatformP256Key.ComponentSize } x || parameters.Q.Y is not { Length: PlatformP256Key.ComponentSize } y)
        {
            return false;
        }

        x.CopyTo(publicX);
        y.CopyTo(publicY);

        return true;
    }


    private static ECParameters ToParameters(byte[]? privateKey, ReadOnlySpan<byte> publicX, ReadOnlySpan<byte> publicY)
    {
        return new ECParameters
        {
            Curve = ECCurve.NamedCurves.nistP256,
            D = privateKey,
            Q = new ECPoint
            {
                X = publicX.ToArray(),
                Y = publicY.ToArray(),
            },
        };
    }


    private static byte[] LeftPad(byte[]? source)
    {
        byte[] padded = new byte[PlatformP256Key.ComponentSize];
        source.AsSpan().CopyTo(padded.AsSpan(PlatformP256Key.ComponentSize - source!.Length));

        return padded;
    }
}
